n=int(input())
count=0
for i in range(1,n+1):
    if n%i==0:
        count+=1
print(count)

n=int(input())
count=0
for x in range(2,n+1):
    prime=True
    for d in range(2,x):
        if x%d==0:
            prime=False
            break
    if prime:
        count+=1
print(count)
